Object.assign(TEXT.en,{currentStandings:'Current standings',afterEvent:'Standings after event',standingsScope:'Cumulative points through',allResults:'All entered results',completeSnapshot:'All results through this event have been entered.',partialSnapshot:'Some results in the selected events are missing — points are provisional.',viewCurrent:'View current standings',backToResults:'Back to the event',nextAfter:'Go to event',lastTiePending:'The final scheduled event tiebreak applies only once that event is included.'});
let standingsThrough=-1;
let lang;try{lang=localStorage.getItem('sm-lang')||'bg';}catch{lang='bg';}if(!TEXT[lang])lang='bg';
const t=k=>TEXT[lang][k]||k, esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), $=s=>document.querySelector(s), fmt=n=>Number(n||0).toLocaleString(lang==='bg'?'bg-BG':'en-GB',{maximumFractionDigits:2});
const STORE='strongman-arena-v1';let doc=SM.document(),queue=[],sync=null,drafts={},view='overview',eventIndex=0,athleteId='',busy=false,net='local',lastServer=null;
let storageStamp=0,storagePending=0,storageDurable=true,damagedStorage=null,lastPayload='',storageReady=false,needsIndexedRecovery=false,readOnlyTab=false,setupFormBase=null,eventFormBase=null,lastSyncError='';
function loadSaved(saved){SM.validateDocument(saved.doc);for(const op of saved.queue||[])SM.validateOperation(op);doc=saved.doc;queue=saved.queue||[];let context=queue.flatMap(op=>op.changes).find(c=>c.path.length===1&&c.path[0]==='data')?.prev?.id||doc.data.id;queue=queue.map(op=>{const updated=op.competitionId?op:{...op,competitionId:context};const root=op.changes.find(c=>c.path.length===1);if(root?.next?.id)context=root.next.id;return updated;});sync=saved.sync||null;drafts=saved.drafts||{};view=saved.view||'overview';eventIndex=saved.eventIndex||0;athleteId=saved.athleteId||'';standingsThrough=Number.isInteger(saved.standingsThrough)?saved.standingsThrough:-1;storageStamp=saved.savedAt||0;}
try{const raw=localStorage.getItem(STORE),saved=JSON.parse(raw||'null');if(saved?.idb){needsIndexedRecovery=true;storageStamp=saved.savedAt||0;}else if(saved)loadSaved(saved);}catch{try{damagedStorage=localStorage.getItem(STORE);}catch{}}
function storageNotice(){refreshFieldStatus();if(readOnlyTab){$('#storageError').innerHTML='<div class="notice error">'+L('Друга съдийска страница на това устройство е активна. Обновете тази страница, преди да редактирате.','Another referee tab on this device is active. Reload this tab before editing.')+'</div>';return;}if(damagedStorage){$('#storageError').innerHTML='<div class="notice error">'+L('Локалният запис е повреден. Оригиналът е запазен и няма да се презаписва.','The saved record is invalid. The original is retained and will not be overwritten.')+' '+button('rawRecovery',L('Изтегли оригинала','Download original'))+' '+button('recoverEmpty',L('Нов празен запис','New empty record'))+'</div>';}else if(!storageDurable&&!storagePending){$('#storageError').innerHTML='<div class="notice error">'+t('storageerror')+' '+button('backup',t('backup'))+'</div>';}else $('#storageError').innerHTML='';}
function persist(){if(!storageReady||damagedStorage||readOnlyTab){storageNotice();return false;}const base={doc,queue,sync,drafts,view,eventIndex,athleteId,standingsThrough};const plain=JSON.stringify(base);if(plain===lastPayload)return storageDurable||storagePending>0;lastPayload=plain;const stamp=Math.max(Date.now(),storageStamp+1);storageStamp=stamp;const payload=JSON.stringify({...base,savedAt:stamp});let localOK=false;try{localStorage.setItem(STORE,payload);localOK=true;}catch{}storageDurable=localOK;storagePending++;storageNotice();SMStorage.save(payload,stamp).then(()=>{if(storageStamp===stamp){storageDurable=true;if(!localOK)try{localStorage.setItem(STORE,JSON.stringify({idb:true,savedAt:stamp}));}catch{}}}).catch(()=>{}).finally(()=>{storagePending--;storageNotice();if($('#savebadge'))$('#savebadge').innerHTML=badge();});return localOK||storagePending>0;}
function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').hidden=true,4200);}
const actor=()=>sync?.actor||localStorage.getItem('sm-actor')||t('by');
function commit(changes,label,extra={}){if(damagedStorage||readOnlyTab)throw Error('DAMAGED_STORAGE');const op=SM.operation(doc,changes,label,actor(),extra);doc=SM.apply(doc,op);if(sync)queue.push(op);persist();render();if(sync)pump();return op;}
function changeData(data,label){return commit([{path:['data'],next:data}],label);}
const d=()=>doc.data, eventName=e=>e?.names?.[lang]||e?.names?.en||'', sourceLinks=ids=>(ids||[]).map(id=>{const s=SOURCES.find(x=>x.id===id);return s?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.name)}</a>`:'';}).join('');
function button(act,label,cls='',attrs=''){return `<button type="button" data-act="${act}" class="${cls}" ${attrs}>${label}</button>`;}
function field(key,label,value='',type='text',attrs=''){return `<div class="field"><label for="${key}">${esc(label)}</label><input id="${key}" name="${key}" type="${type}" value="${esc(value)}" ${attrs}></div>`;}
function select(key,label,options,value){return `<div class="field"><label for="${key}">${esc(label)}</label><select id="${key}" name="${key}">${options.map(([v,l])=>`<option value="${v}" ${value===v?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`;}
const modesOptions=()=>SM.modes.map(x=>[x,t(x)]);
function secondaryOptions(mode){return [['none',t('none')],...(['race','reps','series','medley','height'].includes(mode)?[['all',t(mode==='height'?'heightmiss':'alltime')]]:[]),...(['series','medley'].includes(mode)?[['finishers',t('finishtime')]]:[])];}
function refreshLiveTables(){if(view!=='scoring')return;if($('#checkpointRegion'))$('#checkpointRegion').innerHTML=checkpointBanner();const e=d().events[eventIndex];if(!e)return;if($('#eventLeaderboard'))$('#eventLeaderboard').innerHTML=eventTable(e,SM.eventScores(d(),e),true);if($('#overallLeaderboard'))$('#overallLeaderboard').innerHTML=SM.standings(d()).slice(0,5).map(r=>'<tr><td>'+r.rank+'</td><td>'+esc(r.athlete.name)+'</td><td class="points">'+fmt(r.total)+'</td></tr>').join('');restoreDraft();}
function complete(e){return d().athletes.length>0&&d().athletes.every(a=>d().results[e.id]?.[a.id]);}
function allComplete(){return d().events.length>0&&d().events.every(complete);}
function modeLabel(e){return t(e.mode==='distance'&&e.unit==='deg'?'degrees':e.mode);}
function summary(e){let s=modeLabel(e);if(e.mode==='race'&&e.target)s+=` · ${fmt(e.target)} m`;if(['series','medley'].includes(e.mode)&&e.target)s+=` · ${e.target}`;if(e.cap)s+=` · ${fmt(e.cap)} s`;return s;}
function badge(){if(storagePending&&!storageDurable)return L('Записване на устройството…','Saving on this device…');const key=sync?(net==='conflict'?'conflict':queue.length?'pending':net==='online'?'synced':'offline'):'local';return `<span class="offlineDot"></span>${t(key)}${queue.length?' · '+queue.length:''}`;}
function hero(eye,title,sub,side=''){return `<div class="hero"><div class="bigtitle"><div class="eyebrow">${eye}</div><h1>${esc(title)}</h1><p class="muted">${esc(sub)}</p></div>${side}</div>`;}
function baseSetupView(){const data=d(),locked=data.phase!=='setup';return hero('COMPETITION DESK',t('intro'),t('setupsub'))+`${locked?`<div class="notice">${t('locked')}</div>`:''}<div class="layout"><div><section class="card"><div class="row between"><h2>01 &nbsp; ${t('competition')}</h2><span class="badge">${t('setup')}</span></div><form id="setupForm"><fieldset ${locked?'disabled':''} style="border:0;padding:0;margin:0">${field('title',t('title'),data.title,'text','maxlength="150" placeholder="STRONGMAN OPEN"')}<div class="grid">${field('date',t('date'),data.date,'date')}${field('venue',t('venue'),data.venue,'text','maxlength="200"')}</div>${field('count',t('count'),data.athletes.length||0,'number','min="2" max="150" readonly required')}<div class="field"><label for="names">${t('names')}</label><textarea id="names" name="names" rows="7" placeholder="Иван Иванов&#10;Петър Петров">${esc(data.athletes.map(a=>a.name).join('\n'))}</textarea><p class="caption">${t('nameshelp')}</p></div>${button('saveSetup',t('save'),'dark')}</fieldset></form></section><section class="card"><div class="row between"><h2>02 &nbsp; ${t('events')}</h2>${!locked?button('catalog',`+ ${t('addevent')}`,'small'):''}</div>${data.events.length?data.events.map((e,i)=>`<div class="eventcard"><span class="stepnum">${i+1}</span><div class="grow"><h3>${esc(eventName(e))}</h3><p class="caption">${esc(summary(e))}</p><span class="badge ${e.reviewed?'green':'orange'}">${t(e.reviewed?'reviewed':'review')}</span></div><div class="controls">${button('editEvent',t(locked?'review':'edit'),'small',`data-id="${e.id}"`)}${!locked?button('moveEvent','↑','icon',`data-id="${e.id}" data-dir="-1" aria-label="${t('up')}" ${i===0?'disabled':''}`)+button('moveEvent','↓','icon',`data-id="${e.id}" data-dir="1" aria-label="${t('down')}" ${i===data.events.length-1?'disabled':''}`)+button('removeEvent','×','icon danger',`data-id="${e.id}" aria-label="${t('remove')}"`):''}</div></div>`).join(''):`<div class="empty">${t('noevents')}</div>`}</section></div><aside><section class="card sticky"><h2>03 &nbsp; ${t('rules')}</h2><form id="rulesForm"><fieldset ${locked?'disabled':''} style="border:0;padding:0;margin:0">${select('tie',t('tie'),['shared','countback','last'].map(k=>[k,t(k)]),data.rules.tie)}${select('zero',t('zero'),[['zero',t('zeropoints')],['rank',t('zerorank')]],data.rules.zero)}</fieldset></form><p class="caption">${t('rulehint')}</p><div class="help">${t('startorder')}</div>${!locked?`<div style="margin-top:20px"><label class="check"><input type="checkbox" id="startCheck">${t('startcheck')}</label>${button('start',t('start'),'primary','style="width:100%;margin-top:12px"')}</div>`:button('goScoring',t('scoring'),'primary','style="width:100%;margin-top:20px"')}</section></aside></div>`;}
function openDialog(html){$('#dialog').innerHTML=`<div class="inner">${html}</div>`;$('#dialog').setAttribute('aria-label',$('#dialog').querySelector('h2')?.textContent||L('Диалог','Dialog'));$('#dialog').showModal();}
function dialogHead(title){return `<div class="dialoghead"><h2>${esc(title)}</h2>${button('close','×','icon',`aria-label="${t('close')}"`)}</div>`;}
function showCatalog(){openDialog(dialogHead(t('catalog'))+`<div class="searchrow"><input id="search" placeholder="${t('search')}" aria-label="${t('search')}"><select id="group" aria-label="${t('all')}">${['all','pull','carry','load','press','lift','hold','throw','mixed'].map(x=>`<option value="${x}">${t(x==='hold'?'holdgroup':x)}</option>`).join('')}</select></div><div id="catalogItems" class="catalog"></div>`);filterCatalog();}
function filterCatalog(){const q=($('#search')?.value||'').toLocaleLowerCase(),g=$('#group')?.value||'all';$('#catalogItems').innerHTML=CATALOG.filter(e=>(g==='all'||e.group===g)&&(e.names.bg+' '+e.names.en).toLocaleLowerCase().includes(q)).map(e=>`<article class="card"><span class="badge">${t(e.group==='hold'?'holdgroup':e.group)}</span><h3 style="margin-top:12px">${esc(eventName(e))}</h3><small class="caption">${modeLabel(e)}</small>${button('addEvent',`+ ${t('add')}`,'small',`data-id="${e.id}"`)}</article>`).join('');}
function makeEvent(id){const c=CATALOG.find(e=>e.id===id);return {...SM.clone(c),template:id,id:SM.uid(),target:0,cap:0,secondary:['series','medley'].includes(c.mode)?'all':'none',weights:'',notes:'',reviewed:false};}
function updateEventFields(){const f=$('#eventForm');if(!f)return;const mode=f.elements.namedItem('mode').value,secondary=f.elements.namedItem('secondary'),previous=secondary.value,options=secondaryOptions(mode);$('#distanceUnitField').hidden=mode!=='distance';$('#target').previousElementSibling.textContent=t(mode==='race'?'targetdistance':'targetcount');secondary.innerHTML=options.map(([value,label])=>'<option value="'+value+'">'+label+'</option>').join('');secondary.value=options.some(([value])=>value===previous)?previous:'none';}
function restoreEventDraft(){const f=$('#eventForm'),draft=drafts.event;if(!f||!draft||draft.id!==f.dataset.id)return;const values=draft.values||{};if(values.mode)f.elements.namedItem('mode').value=values.mode;updateEventFields();for(const el of f.elements){if(!el.name)continue;if(el.type==='checkbox')el.checked=values[el.name]==='on';else if(el.name==='secondary')el.value=[...el.options].some(option=>option.value===values.secondary)?values.secondary:'none';else if(Object.hasOwn(values,el.name))el.value=values[el.name];}}

function editEvent(id){eventFormBase=SM.clone(d().events);const e=d().events.find(x=>x.id===id),locked=d().phase!=='setup';openDialog(dialogHead(eventName(e))+conanUnitNotice(e)+`<div class="notice">${t('suggested')}</div><form id="eventForm" data-id="${e.id}"><fieldset ${locked?'disabled':''} style="border:0;margin:0;padding:0"><div class="grid">${field('bg',t('eventbg'),e.names.bg,'text','required maxlength="150"')}${field('en',t('eventen'),e.names.en,'text','required maxlength="150"')}</div>${select('mode',t('mode'),modesOptions(),e.mode)}<div id="distanceUnitField" ${e.mode==='distance'?'':'hidden'}>${select('unit',L('Мерна единица','Unit'),[['m',L('Метри — m','Metres — m')],['deg',L('Градуси — °','Degrees — °')]],e.unit||'m')}</div><div class="grid">${field('target',t(e.mode==='race'?'targetdistance':'targetcount'),e.target,'text','inputmode="decimal"')}${field('cap',t('cap'),e.cap,'text','inputmode="decimal"')}</div>${select('secondary',t('secondary'),secondaryOptions(e.mode),e.secondary)}${field('weights',t('weights'),e.weights,'text','maxlength="500"')}<div class="field"><label for="notes">${t('notes')}</label><textarea name="notes" id="notes" maxlength="4000">${esc(e.notes)}</textarea></div><label class="check"><input type="checkbox" name="reviewed" ${e.reviewed?'checked':''}>${t('reviewed')}</label>${!locked?`<div class="savebar"><button class="primary" type="submit">${t('save')}</button></div>`:''}</fieldset></form><details><summary>${t('sources')}</summary><div class="sources">${sourceLinks(e.sources)}</div></details>`);restoreEventDraft();}
function saveSetup(silent=false){const f=$('#setupForm');if(!f||d().phase!=='setup')return true;const fd=new FormData(f),names=String(fd.get('names')).split('\n').map(x=>x.trim()).filter(Boolean),n=Number(fd.get('count'));if(names.length!==n||n<2||n>150||new Set(names.map(s=>s.toLocaleLowerCase())).size!==n){if(!silent)toast(t('emptyNames'));return false;}const data=SM.clone(d());data.title=String(fd.get('title')).trim()||'Strongman';data.date=String(fd.get('date'));data.venue=String(fd.get('venue')).trim();data.athletes=names.map((name,i)=>({id:data.athletes[i]?.id||SM.uid(),name,bib:i+1}));data.rules={tie:$('#tie').value,zero:$('#zero').value};const base=drafts.setup?.base||setupFormBase||d();const changes=['title','date','venue','athletes','rules'].filter(k=>JSON.stringify(data[k])!==JSON.stringify(base[k])).map(k=>({path:['data',k],prev:base[k],next:data[k]}));if(changes.length)commit(changes,'setup');delete drafts.setup;persist();render();return true;}
function modeRule(e){if(e.mode==='distance'&&e.unit==='deg')return L('По-големият общ ъгъл печели. Една обиколка = 360°. Въведете всички обиколки плюс остатъка в градуси: 2 обиколки + 90° = 810°. Няма ограничение до 360°. Равните градуси делят точките.','The greatest total angle wins. One revolution = 360°. Enter all revolutions plus the remainder in degrees: 2 revolutions + 90° = 810°. Values may exceed 360°. Equal angles share points.');const bg={race:'Завършилите са пред всички незавършили и се подреждат по по-кратко време. Незавършилите — по повече изминати метри. Равно разстояние е равен резултат, освен ако предварително е избрано време до измервателната точка.',reps:'Броят се само повторенията, признати от съдията. При равен брой точките се делят, освен ако предварително е включено време до последното зачетено повторение.',max:'Сравнява се най-тежкият успешен опит. Еднаквите тежести са равни; телесно тегло и брой опити не се използват автоматично. Запишете опитите в бележката.',hold:'По-дългото валидно задържане печели. Времето се спира при съдийския критерий за загуба на позиция или хват.',distance:'По-голямата валидна дистанция в метри печели. За Колелото на Конан използвайте мерна единица „Градуси“.',series:'Повече завършени снаряди или стъпки печелят. При включено време се сравнява времето до последния зачетен успех; при „само пълна серия“ частичните равни бройки делят точки.',medley:'Първо повече завършени етапи, после повече метри в следващия етап, после времето според избраната настройка. Не събирайте несъпоставими метри от различни етапи. Необходима е ясна последователност.',height:'По-голяма успешно преодоляна височина печели. Само ако е включено: по-малко неуспехи на най-добрата височина, после по-малко общо. Иначе равното постижение дели точки.',tiers:'Повече повторения с най-тежкия уред печелят, после със средния, после с най-лекия. Едно тежко повторение побеждава произволен брой по-леки. Тежестите и редът трябва да са еднакви за всички.',manual:t('manualhint')},en={race:'Finishers rank ahead of every non-finisher and are ordered by faster time. Non-finishers rank by greater distance. Equal distance ties unless time to a measured checkpoint was agreed in advance.',reps:'Count only referee-approved repetitions. Equal counts share points unless time to the last valid rep was enabled before the start.',max:'Rank the heaviest successful attempt. Equal weights tie. Bodyweight and attempt count are not automatic tiebreakers. Record attempts in the note.',hold:'The longest valid hold wins. Timing ends at the referee’s defined position or grip failure.',distance:'The greatest valid distance in metres wins. For Conan’s wheel choose the Degrees unit.',series:'More completed implements or steps wins. If timing is enabled use the split at the last valid success. With finishers-only timing, equal partial counts share points.',medley:'Compare completed stages first, then metres into the next stage, then time under the selected policy. Do not add incomparable metres from different stages. Define a clear stage order.',height:'Greater successful height wins. Only when enabled: fewer misses at the best height, then fewer total misses. Otherwise equal heights share points.',tiers:'Compare heavy reps first, then medium reps, then light reps. One heavier rep beats any number of lighter reps. Loads and order must be the same for everyone.',manual:t('manualhint')};return (lang==='bg'?bg:en)[e.mode];}
function resultFields(e,r={}){const active=['ok','dnf'].includes(r.status||'ok');if(!active)return '';const inp=(k,label,major=false)=>{let html=field(k,t(label),r[k]??'','text',`inputmode="decimal" autocomplete="off"`);const unit={time:'s',distance:SM.distanceUnit(e),weight:'kg',reps:L('повт.','reps'),height:'m',count:e.target?'/ '+e.target:''}[k];if(major&&unit)html=html.replace('<input','<div class="measurement-entry"><input').replace(/<\/div>$/,`<span class="measurement-unit" aria-hidden="true">${esc(unit)}</span></div></div>`);return `<div class="${major?'major':''}">${html}</div>`;};let html='';switch(e.mode){case'race':html=r.status==='dnf'?inp('distance','distancefield',true)+(e.secondary==='all'?inp('time','time'):''):inp('time','time',true);break;case'reps':html=inp('reps','repsfield',true)+(e.secondary==='all'?inp('time','time'):'');break;case'max':html=inp('weight','weight',true);break;case'hold':html=inp('time','holdfield',true);break;case'distance':html=inp('distance',e.unit==='deg'?'degreesfield':'distancefield',true)+(e.unit==='deg'?'<p class="caption">'+L('1 обиколка = 360° · 2 обиколки + 90° = 810°. Въведете общия ъгъл.','1 revolution = 360° · 2 revolutions + 90° = 810°. Enter the total angle.')+'</p>':'');break;case'series':case'medley':html=inp('count','countfield',true)+(e.mode==='medley'?inp('partial','partial'):'')+(e.secondary!=='none'?inp('time','time'):'');break;case'height':html=inp('height','heightfield',true)+(e.secondary==='all'?`<div class="grid">${inp('misses','misses')}${inp('totalMisses','totalMisses')}</div>`:'');break;case'tiers':html=inp('heavy','heavy')+inp('medium','medium')+inp('light','light');break;case'manual':html=inp('placing','placing',true);break;}return html;}
function draftKey(){return d().id+':'+(d().events[eventIndex]?.id||'')+':'+athleteId;}
function draftResult(){return drafts[draftKey()]?.values||d().results[d().events[eventIndex]?.id]?.[athleteId]||{status:'ok'};}

function scopeCount(){if(view==='eventStandings')return Math.min(eventIndex+1,d().events.length);return standingsThrough<1?d().events.length:Math.min(standingsThrough,d().events.length);}
function completedPrefix(){let n=0;for(const e of d().events){if(!complete(e))break;n++;}return n;}
function checkpointBanner(){const n=completedPrefix();if(!n)return '';const rows=SM.standings(d(),n);return '<section class="notice good row between" id="checkpointBanner"><div class="grow"><strong>'+t('afterEvent')+' '+n+' · '+esc(eventName(d().events[n-1]))+'</strong><p class="caption" style="margin:6px 0 0">'+rows.slice(0,3).map(r=>(r.tied?'=':'')+r.rank+'. '+esc(r.athlete.name)+' · '+fmt(r.total)+' '+t('points').toLowerCase()).join(' &nbsp; / &nbsp; ')+'</p></div>'+button('checkpoint',t('viewCurrent'),'small', 'data-through="'+n+'"')+'</section>';}
function openStandings(through=-1){captureDraft();standingsThrough=through;view='standings';persist();render();window.scrollTo(0,0);}

function baseScoringView(){if(d().phase==='setup')return hero('FIELD DESK',t('scoring'),t('notstarted'))+button('setup',t('setup'),'primary');const e=d().events[eventIndex];if(!e)return '';if(!d().athletes.some(a=>a.id===athleteId))athleteId=d().athletes[0]?.id;const r=draftResult(),rows=SM.eventScores(d(),e),entered=rows.filter(x=>x.result).length;return hero(d().phase==='finished'?t('done'):t('running'),d().title||'Strongman',`${d().venue} · ${d().date}`,`<div class="stats"><div><div class="stat">${d().events.filter(complete).length}/${d().events.length}</div><span class="caption">${t('complete')}</span></div></div>`)+'<div id="checkpointRegion">'+checkpointBanner()+'</div>'+`<div class="eventtabs noprint">${d().events.map((ev,i)=>button('selectEvent',`${complete(ev)?'✓ ':''}${i+1}. ${esc(eventName(ev))}`,i===eventIndex?'active':'',`data-index="${i}"`)).join('')}</div><div class="layout"><div><section class="card"><div class="runhead"><span class="stepnum">${eventIndex+1}</span><div><span class="eyebrow">${t('event')} ${eventIndex+1} ${t('of')} ${d().events.length}</span><h2 style="margin:5px 0 0">${esc(eventName(e))}</h2></div></div><div class="metricline"><span class="badge">${esc(summary(e))}</span><span class="badge ${complete(e)?'green':'orange'}">${entered}/${rows.length} ${t('entered')}</span></div><div class="progress"><i style="width:${100*entered/rows.length}%"></i></div><details><summary>${t('rules')}</summary><p class="caption">${modeRule(e)}</p><p class="eventnote caption">${esc(e.weights)}<br>${esc(e.notes)}</p></details><form id="resultForm" class="resultinput" data-event="${e.id}" data-athlete="${athleteId}">${select('athlete',t('selectathlete'),d().athletes.map(a=>[a.id,`${a.bib}. ${a.name}${d().results[e.id]?.[a.id]?' ✓':''}`]),athleteId)}<fieldset ${d().phase==='finished'?'disabled':''} style="border:0;padding:0;margin:0">${select('status',t('status'),[['ok',t('ok')],...(e.mode==='race'?[['dnf',t('dnf')]]:[]),['zero',t('zeroStatus')],['dns',t('dns')],['wd',t('wd')],['dq',t('dq')]],r.status||'ok')}<div id="resultFields">${resultFields(e,r)}</div><details ${Number(r.penalty)>0||Number(r.deduction)>0?'open':''}><summary>${t('penalty')} / ${t('deduction')}</summary><div class="grid">${field('penalty',t('penalty'),r.penalty||0,'text','inputmode="decimal"')}${field('deduction',t('deduction'),r.deduction||0,'text','inputmode="decimal"')}</div></details><div class="field"><label for="note">${t('resultnote')}</label><textarea id="note" name="note" maxlength="4000">${esc(r.note||'')}</textarea><p class="caption">${t('resultnotehelp')}</p></div><p class="caption" id="draftInfo">${t('draft')}</p><div class="savebar"><button type="submit" class="dark">${t('save')}</button>${button('saveNext',t('saveNext'),'primary')}</div></fieldset></form>${d().phase==='finished'?button('reopen',t('reopen'),'primary'):''}</section><div class="row between noprint">${button('prevEvent','← '+t('previous'),'',''+(eventIndex===0?'disabled':''))}${eventIndex<d().events.length-1?button('nextEvent',t('next')+' →','dark',!complete(e)?'disabled':''):button('finish',t('finish'),'primary',!allComplete()?'disabled':'')}</div><p class="caption" style="margin-top:12px">${t('finishhint')}</p></div><aside><div class="card"><h2>${t('event')} ${eventIndex+1} · ${t('standings')}</h2><div class="tablewrap" id="eventLeaderboard">${eventTable(e,rows,true)}</div></div><div class="scorebox"><h2>${t('standings')}</h2><table><tbody id="overallLeaderboard">${SM.standings(d()).slice(0,5).map(r=>`<tr><td>${r.rank}</td><td>${esc(r.athlete.name)}</td><td class="points">${fmt(r.total)}</td></tr>`).join('')}</tbody></table>${button('standings',t('showdetails'),'small','style="margin-top:14px"')}</div><p class="caption">${t('precision')}</p></aside></div>`;}
function performance(e,r){if(!r)return '—';if(['zero','dns','wd','dq'].includes(r.status))return t(r.status==='zero'?'zeroStatus':r.status);let s='';switch(e.mode){case'race':s=r.status==='dnf'?`${fmt(r.distance)} m · DNF`:`${fmt(r.time)} s`;break;case'reps':s=`${r.reps} ${lang==='bg'?'повт.':'reps'}`;break;case'max':s=`${fmt(r.weight)} kg`;break;case'hold':s=`${fmt(r.time)} s`;break;case'distance':s=`${fmt(r.distance)} ${SM.distanceUnit(e)}`;break;case'series':case'medley':s=`${r.count}/${e.target}`+(e.mode==='medley'&&r.partial?` + ${fmt(r.partial)} m`:'');break;case'height':s=`${fmt(r.height)} m`+(e.secondary==='all'?` (${r.misses}/${r.totalMisses})`:'');break;case'tiers':s=`${r.heavy} / ${r.medium} / ${r.light}`;break;case'manual':s=`#${r.placing}`;}
 if(['reps','series','medley'].includes(e.mode)&&r.time&&e.secondary!=='none')s+=` · ${fmt(r.time)} s`;if(r.penalty)s+=` +${fmt(r.penalty)} s`;if(r.deduction)s+=` −${fmt(r.deduction)} ${t('points').toLowerCase()}`;return s;}
function eventTable(e,rows,clickable=false){return `<table><thead><tr><th>${t('place')}</th><th>${t('name')}</th><th>${t('result')}</th><th>${t('points')}</th></tr></thead><tbody>${rows.map(r=>`<tr ${clickable?`class="resultrow" data-act="selectAthlete" data-id="${r.athlete.id}" tabindex="0"`:''}><td class="rank ${r.rank===1?'top':''}">${r.rank?(r.tied?'=':'')+r.rank:'—'}</td><td class="name">${esc(r.athlete.name)}</td><td>${esc(performance(e,r.result))}</td><td class="points">${r.points===null?'—':fmt(r.points)}</td></tr>`).join('')}</tbody></table>`;}
function captureDraft(){const f=$('#resultForm');if(!f)return;const values=Object.fromEntries(new FormData(f));delete values.athlete;const old=drafts[draftKey()];drafts[draftKey()]={values,base:old&&Object.hasOwn(old,'base')?old.base:SM.clone(SM.get(doc,['data','results',f.dataset.event,f.dataset.athlete])),at:new Date().toISOString()};persist();}
function restoreDraft(){const draft=drafts[draftKey()];if(!draft)return;const current=SM.get(doc,['data','results',d().events[eventIndex].id,athleteId]);const stale=Object.hasOwn(draft,'base')&&JSON.stringify(draft.base)!==JSON.stringify(current);$('#draftInfo').innerHTML=stale?'<span class="notice error" style="display:block">'+t('stale')+'</span>'+button('reloadResult',t('reloadResult'),'small'):t('draftrestored')+' · '+t('draft');}
function saveResult(next=false){const e=d().events[eventIndex],f=$('#resultForm');if(!f||d().phase!=='live')return;const fd=Object.fromEntries(new FormData(f)),r={status:fd.status,penalty:SM.number(fd.penalty||0),deduction:SM.number(fd.deduction||0),note:fd.note||''};for(const k of ['reps','time','distance','weight','count','partial','height','misses','totalMisses','heavy','medium','light','placing'])if(fd[k]!==undefined){r[k]=k==='time'?SM.time(fd[k]):SM.number(fd[k]);if(fd[k]===''&&['partial','heavy','medium','light','misses','totalMisses'].includes(k))r[k]=0;}
 try{SM.validateResult(e,r);}catch(err){resultError(err);return false;}
 const path=['data','results',e.id,athleteId];try{commit([{path,next:r,...(drafts[draftKey()]&&Object.hasOwn(drafts[draftKey()],'base')?{prev:drafts[draftKey()].base}:{})}],`${t('result')}: ${d().athletes.find(a=>a.id===athleteId).name} · ${eventName(e)}`);}catch(err){toast(t(err.message==='CONFLICT'?'stale':'error'));restoreDraft();return false;}savedReceipt={competitionId:d().id,eventId:e.id,athleteId,value:JSON.stringify(r)};delete drafts[draftKey()];if(next){const nextId=d().athletes.find(a=>!d().results[e.id]?.[a.id])?.id;if(nextId)athleteId=nextId;else view='eventReview';}persist();render();if(view==='eventReview'){window.scrollTo(0,0);$('#reviewHeading')?.focus();}if(next&&d().athletes.some(a=>!d().results[e.id]?.[a.id]))$('#resultFields input')?.focus();toast(d().athletes.find(a=>a.id===savedReceipt.athleteId).name+' · '+performance(e,r)+' · '+t(sync&&queue.length?'savepending':'saved'));return true;}
function standingsView(review=false){
 const n=scopeCount(),events=d().events.slice(0,n),rows=SM.standings(d(),n),full=events.length>0&&events.every(complete),milestone=review||standingsThrough>0,final=d().phase==='finished'&&allComplete()&&n===d().events.length;
 const heading=milestone?t('afterEvent')+' '+n:t(final?'final':'currentStandings');
 const scopeSelect=review?'<strong>'+t('afterEvent')+' '+n+' · '+esc(eventName(d().events[eventIndex]))+'</strong>':select('standingsThrough',t('standingsScope'),[['-1',t('allResults')],...d().events.map((e,i)=>[String(i+1),t('afterEvent')+' '+(i+1)+' · '+eventName(e)])],String(standingsThrough));
 const resume=review?button('reviewEvent',L('← Обзор на дисциплината','← Event overview'))+(n<d().events.length?button('reviewNext',L('Следваща дисциплина →','Next event →'),'primary',full?'':'disabled'):d().phase==='live'?button('finish',t('finish'),'primary',allComplete()?'':'disabled'):button('nav',t('final'),'primary','data-view="standings"')):d().phase==='live'?button('resumeEvent',t('backToResults'),'','data-index="'+eventIndex+'"')+(milestone&&full&&n<d().events.length?button('resumeEvent',t('nextAfter')+' '+(n+1)+' →','dark','data-index="'+n+'"'):''):'';
 return (review?reviewSteps(2):'')+hero(final?t('done'):t('currentStandings'),review&&!final?L('Временно общо класиране','Provisional overall standings'):heading,d().title||'Strongman')+
 '<section class="card noprint"><div class="grid"><div>'+scopeSelect+'</div><div class="row" style="align-self:center">'+resume+'</div></div><p class="caption" style="margin:0">'+t(full?'completeSnapshot':'partialSnapshot')+'</p></section>'+
 (!full?'<div class="notice">'+t('partialSnapshot')+'</div>':'')+
 (d().rules.tie==='last'&&n<d().events.length?'<div class="notice">'+t('lastTiePending')+'</div>':'')+
 (queue.length?'<div class="notice">'+t('pendingexport')+'</div>':'')+
 '<div class="row noprint" style="margin-bottom:20px">'+button('word',t('exportword'),'primary')+button('print',t('print'))+button('csv',t('exportcsv'))+button('backup',t('backup'))+'</div>'+
 (rows.length?'<div class="podium">'+rows.slice(0,3).map(r=>'<div class="card"><span class="eyebrow">'+t('place')+' '+(r.tied?'=':'')+r.rank+'</span><h3>'+esc(r.athlete.name)+'</h3><div class="stat">'+fmt(r.total)+'</div><span class="caption">'+t('points')+(r.tied?' · '+t('same'):'')+'</span></div>').join('')+'</div><div class="card"><h2>'+esc(d().title)+'</h2><p class="caption">'+esc(d().venue)+' · '+esc(d().date)+' · '+t('athletes')+': '+d().athletes.length+'</p>'+standingsResults(rows,events)+'<p class="caption" style="margin-top:15px">'+t('tie')+': '+t(d().rules.tie)+' · '+t('zero')+': '+t(d().rules.zero==='zero'?'zeropoints':'zerorank')+'</p></div><h2 style="margin:25px 0">'+t('showdetails')+'</h2>'+events.map((e,i)=>'<details class="card"><summary>'+(i+1)+'. '+esc(eventName(e))+'</summary><div class="tablewrap">'+eventTable(e,SM.eventScores(d(),e))+'</div></details>').join('')+'<p class="printonly">'+t('printsign')+'</p>':'<div class="card empty">'+t('noexport')+'</div>');
}
function historyView(){return hero('AUDIT LOG',t('history'),t('lastchange')+' · '+doc.revision)+`<div class="row" style="margin-bottom:20px">${button('undo','↶ '+t('undo'),'dark',doc.undo.length?'':'disabled')}${button('redo','↷ '+t('redo'),'',doc.redo.length?'':'disabled')}${button('backup',t('backup'))}</div><div class="card">${doc.log.length?doc.log.slice().reverse().map(x=>`<div class="historyline"><div class="row between"><strong>${esc(['setup','start','finish','reopen','undo','redo','new'].includes(x.label)?t({start:'start',finish:'finish',new:'new',setup:'setup',reopen:'reopen',undo:'undo',redo:'redo'}[x.label]):x.label)}</strong><span class="caption">${new Date(x.at).toLocaleString(lang==='bg'?'bg-BG':'en-GB')}</span></div><p class="caption">${t('by')}: ${esc(x.actor)} · ${esc(x.id.slice(0,8))}</p><details><summary>${t('changes')}</summary><pre>${esc(JSON.stringify(x.changes,null,2))}</pre></details></div>`).join(''):`<div class="empty">${t('nohistory')}</div>`}</div>`;}
function guideView(){return hero('KNOW THE RULES',t('guideTitle'),t('guideSub'))+`<div class="notice">${t('scope')}</div><div class="layout"><div><div class="card ruletext"><h2>${t('rules')}</h2><p>${t('rulebody')}</p><h3 style="margin-top:22px">${t('zero')}</h3><p>${t('zerobody')}</p><h3 style="margin-top:22px">${t('tie')}</h3><p>${t('tiebody')}</p></div><div class="card ruletext"><h2>${lang==='bg'?'Български състезания':'Bulgarian competitions'}</h2><p>${t('bgbody')}</p></div><div class="card"><h2>${t('measure')}</h2>${SM.modes.map(mode=>`<details><summary>${t(mode)}</summary><p class="caption">${modeRule({mode})}</p></details>`).join('')}<details><summary>${t('degrees')}</summary><p class="caption">${modeRule({mode:'distance',unit:'deg'})}</p></details></div><div class="help">${t('safetybody')}</div></div><aside><div class="card sources"><h2>${t('sources')}</h2><p class="caption">${t('sourcesnote')}</p>${sourceLinks(SOURCES.map(x=>x.id))}</div></aside></div>`;}
function download(name,blob){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
function backup(){download('strongman-backup-'+new Date().toISOString().slice(0,19).replace(/:/g,'-')+'.json',new Blob([JSON.stringify({app:'StrongmanArena',version:1,exported:new Date().toISOString(),doc,queue,drafts},null,2)],{type:'application/json'}));}
async function request(url,key,path,options={}){const res=await fetch(url+path,{...options,headers:{'Authorization':'Bearer '+key,'Content-Type':'application/json',...(options.headers||{})},signal:AbortSignal.timeout(8000)});if(res.status===304)return null;const body=await res.json();if(!res.ok)throw Object.assign(Error(body.error||'NETWORK'),{status:res.status});return body;}
async function connect(create){if(busy||sync&&queue.length){toast(t('onlineleave'));return;}const f=$('#syncForm');if(!f.reportValidity())return;const fd=new FormData(f),url=String(fd.get('server')).replace(/\/$/,''),key=String(fd.get('key')),name=String(fd.get('actor')).trim();try{let remote=await request(url,key,'/api/state');if(create){if(remote.doc){toast(t('serverexists'));return;}remote=await request(url,key,'/api/init',{method:'POST',body:JSON.stringify({doc})});}else{if(!remote.doc){toast(t('serverempty'));return;}if(!await seasonConfirm(t('confirmjoin')))return;backup();}SM.validateDocument(remote.doc);doc=remote.doc;sync={url,key,actor:name};localStorage.setItem('sm-actor',name);queue=[];net='online';lastServer=SM.clone(doc);persist();render();toast(t('synced'));}catch{toast(t('syncerror'));}}
function syncNotice(){refreshFieldStatus();const box=$('#syncAlert');if(!box)return;box.innerHTML=net==='conflict'?'<div class="notice error">'+L('Общата синхронизация е спряна. Локалните промени са запазени.','Shared sync is paused. Local changes are retained.')+' '+esc(lastSyncError)+' '+button('nav',t('connect'),'small','data-view="connect"')+' '+button('backup',t('backup'))+'</div>':'';}
async function pump(){if(!sync||busy||net==='conflict'||readOnlyTab||!storageReady||damagedStorage)return;busy=true;const conf=sync;try{while(queue.length){const op=queue[0],remote=await request(conf.url,conf.key,'/api/op',{method:'POST',body:JSON.stringify(op)});if(sync!==conf)return;queue.shift();lastServer=remote.doc;let merged=remote.doc;try{for(const waiting of queue)merged=SM.apply(merged,waiting);}catch{persist();throw Error('CONFLICT');}doc=merged;persist();}const remote=await request(conf.url,conf.key,'/api/state',{headers:doc.revision===lastServer?.revision?{'If-None-Match':'"'+doc.revision+'"'}:{}});if(sync!==conf)return;if(remote?.doc&&JSON.stringify(remote.doc)!==JSON.stringify(doc)){SM.validateDocument(remote.doc);if(remote.doc.data.id!==doc.data.id&&queue.length)throw Error('CONFLICT');lastServer=remote.doc;let rebased=remote.doc;for(const waiting of queue)rebased=SM.apply(rebased,waiting);doc=rebased;persist();if(!$('#dialog').open&&!document.activeElement?.matches('input,textarea,select'))render();else refreshLiveTables();}net='online';lastSyncError='';}catch(err){net=err.message==='CONFLICT'||[400,401,409,413].includes(err.status)?'conflict':'offline';lastSyncError=err.message==='UPDATE_REQUIRED'?L('Обновете приложението на всички съдийски устройства.','Refresh the app on all judge devices.'):err.status===401?L('Проверете кода за достъп.','Check the access code.'):err.status===413?L('Архивът надвишава лимита за общата сесия.','The shared session size limit was exceeded.'):'';}finally{busy=false;$('#savebadge').innerHTML=badge();syncNotice();if(view==='connect'&&!$('#dialog').open&&!document.activeElement?.matches('input,textarea,select'))render();}}

document.addEventListener('click',async ev=>{const b=ev.target.closest('[data-act]');if(!b||b.disabled)return;const act=b.dataset.act,id=b.dataset.id;try{
 if(await uxAction(act,b))return;
 if(await seasonAction(act,id))return;
 if(act==='nav'){$('#dialog').close();if(view==='setup')captureSetupDraft();captureDraft();if(b.dataset.view==='standings')standingsThrough=-1;view=b.dataset.view;persist();render();window.scrollTo(0,0);}
 else if(act==='checkpoint'){openStandings(Number(b.dataset.through));}else if(act==='resumeEvent'){view='scoring';eventIndex=Number(b.dataset.index);athleteId=d().athletes[0]?.id;persist();render();window.scrollTo(0,0);}else if(['setup','goScoring','standings'].includes(act)){if(act==='standings')standingsThrough=-1;view=act==='goScoring'?'scoring':act;persist();render();}
 else if(act==='language'){captureDraft();captureSetupDraft();lang=lang==='bg'?'en':'bg';localStorage.setItem('sm-lang',lang);$('#dialog').close();render();applySetupDraft();}
 else if(act==='saveSetup'){if(saveSetup())toast(t('saved'));}
 else if(act==='catalog'){captureSetupDraft();showCatalog();}
 else if(act==='close'){$('#dialog').close();delete drafts.event;persist();applySetupDraft();}
 else if(act==='addEvent'){const e=makeEvent(id);const events=[...d().events,e];commit([{path:['data','events'],next:events}],'Add event: '+eventName(e));$('#dialog').close();editEvent(e.id);}
 else if(act==='editEvent'){captureSetupDraft();editEvent(id);}
 else if(act==='removeEvent'){captureSetupDraft();if(await seasonConfirm(t('confirmremove')))commit([{path:['data','events'],next:d().events.filter(e=>e.id!==id)}],'Remove event');applySetupDraft();}
 else if(act==='moveEvent'){captureSetupDraft();const events=SM.clone(d().events),i=events.findIndex(x=>x.id===id),j=i+Number(b.dataset.dir);if(j>=0&&j<events.length){[events[i],events[j]]=[events[j],events[i]];commit([{path:['data','events'],next:events}],'Reorder events');}applySetupDraft();}
 else if(act==='start'){const checked=$('#startCheck').checked;if(!saveSetup())return;if(!d().events.length||!d().events.every(e=>e.reviewed)){toast(t('reviewall'));return;}if(!checked){toast(t('startcheck'));return;}commit([{path:['data','phase'],next:'live'}],'start');view='scoring';persist();render();}
 else if(act==='selectEvent'||act==='nextEvent'||act==='prevEvent'){captureDraft();eventIndex=act==='selectEvent'?Number(b.dataset.index):eventIndex+(act==='nextEvent'?1:-1);athleteId=d().athletes[0]?.id;persist();render();}
 else if(act==='selectAthlete'){captureDraft();athleteId=id;persist();render();($('#resultFields input')||$('#athlete'))?.focus();}
 else if(act==='saveNext')saveResult(true);else if(act==='reloadResult'){backup();delete drafts[draftKey()];persist();render();}
 else if(act==='finish'){if(!allComplete()){toast(t('incomplete'));return;}commit([{path:['data','phase'],next:'finished'}],'finish');view='standings';standingsThrough=-1;persist();render();}
 else if(act==='reopen')commit([{path:['data','phase'],next:'live'}],'reopen');
 else if(act==='undo'||act==='redo'){const op=SM.reverse(doc,act==='redo',actor());if(op){doc=SM.apply(doc,op);if(sync)queue.push(op);persist();render();pump();}}
 else if(act==='backup')backup();
 else if(act==='word'){if(!d().athletes.length){toast(t('noexport'));return;}download('strongman-results.docx',makeWord(scopeCount()));}
 else if(act==='print'){view='standings';render();window.print();}
 else if(act==='csv'){const rows=[[t('place'),t('name'),...d().events.slice(0,scopeCount()).map(eventName),t('total')],...SM.standings(d(),scopeCount()).map(r=>[r.rank,r.athlete.name,...r.events.map(x=>x.points??''),r.total])];download('strongman-results.csv',new Blob(['\ufeff'+rows.map(r=>r.map(x=>'"'+SM.csvCell(x).replace(/"/g,'""')+'"').join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));}
 else if(act==='restore')$('#importFile').click();
 else if(act==='join'||act==='publish')await connect(act==='publish');
 else if(act==='retry'){net='offline';await pump();render();}
 else if(act==='disconnect'){if(queue.length){toast(t('onlineleave'));return;}sync=null;net='local';persist();render();}
 else if(act==='discard'){backup();if(!confirm(t('confirmjoin')))return;const remote=await request(sync.url,sync.key,'/api/state');queue=[];doc=remote.doc;net='online';persist();render();}
 else if(act==='new'){$('#dialog').close();if(queue.length){toast(t('onlineleave'));return;}captureDraft();captureSetupDraft();const before=SM.clone(d());if(!await seasonConfirm(L('Да започна ново състезание? Текущото ще бъде заменено след изтегляне на JSON архив. Сезонът и записаните в него кръгове се запазват.','Start a new competition? The current one will be replaced after downloading a JSON backup. The season and its saved rounds are retained.')+(sync?' '+t('newlive'):'')))return;if(queue.length){toast(t('onlineleave'));return;}if(JSON.stringify(before)!==JSON.stringify(d()))throw Error('CONFLICT');backup();const fresh=SM.fresh();if(d().season)fresh.season=SM.clone(d().season);if(d().audience)fresh.audience=SM.clone(d().audience);changeData(fresh,'new');drafts={};savedReceipt=null;view='setup';standingsThrough=-1;athleteId='';eventIndex=0;persist();render();window.scrollTo(0,0);$('#title')?.focus();}
 else if(act==='downloadHtml'){const copy=document.documentElement.cloneNode(true);copy.querySelector('#main').innerHTML='';copy.querySelector('#nav').innerHTML='';copy.querySelector('#dialog').innerHTML='';copy.querySelector('#dialog').removeAttribute('open');copy.querySelector('#savebadge').innerHTML='';copy.querySelector('#toast').hidden=true;download('strongman-arena.html',new Blob(['<!doctype html>'+copy.outerHTML],{type:'text/html;charset=utf-8'}));}
 }catch(err){toast(t(err.message==='CONFLICT'?'stale':'error'));if(err.message==='CONFLICT'&&view==='scoring')restoreDraft();}});
function captureSetupDraft(){const f=$('#setupForm');if(f&&d().phase==='setup'){drafts.setup={base:drafts.setup?.base||setupFormBase||SM.clone(d()),values:Object.fromEntries(new FormData(f)),tie:$('#tie')?.value,zero:$('#zero')?.value};persist();}}
function applySetupDraft(){if(view!=='setup'||d().phase!=='setup'||!drafts.setup)return;for(const [k,v]of Object.entries(drafts.setup.values))if($('#setupForm').elements.namedItem(k))$('#setupForm [name="'+k+'"]').value=v;if($('#tie'))$('#tie').value=drafts.setup.tie;if($('#zero'))$('#zero').value=drafts.setup.zero;}
document.addEventListener('input',ev=>{if(ev.target.id==='search')filterCatalog();if(ev.target.closest('#eventForm')){drafts.event={id:$('#eventForm').dataset.id,base:drafts.event?.base||eventFormBase,values:Object.fromEntries(new FormData($('#eventForm')))};persist();}if(ev.target.closest('#resultForm'))captureDraft();if(ev.target.closest('#setupForm')||ev.target.closest('#rulesForm'))captureSetupDraft();});
document.addEventListener('change',ev=>{if(ev.target.id==='mode'&&ev.target.closest('#eventForm'))updateEventFields();if(ev.target.closest('#eventForm')){drafts.event={id:$('#eventForm').dataset.id,base:drafts.event?.base||eventFormBase,values:Object.fromEntries(new FormData($('#eventForm')))};persist();}if(ev.target.id==='standingsThrough'){standingsThrough=Number(ev.target.value);persist();render();}if(ev.target.id==='group')filterCatalog();if(ev.target.id==='athlete'){captureDraft();athleteId=ev.target.value;persist();render();}if(ev.target.id==='status'){captureDraft();render();}});
document.addEventListener('submit',ev=>{ev.preventDefault();if(ev.target.id==='resultForm')saveResult();if(ev.target.id==='setupForm')saveSetup();if(ev.target.id==='eventForm'){const f=ev.target;if(!f.reportValidity())return;const fd=Object.fromEntries(new FormData(f)),events=SM.clone(d().events),e=events.find(x=>x.id===f.dataset.id);e.names={bg:fd.bg.trim(),en:fd.en.trim()};e.mode=fd.mode;if(e.mode==='distance')e.unit=fd.unit||'m';else delete e.unit;e.target=SM.number(fd.target);e.cap=SM.number(fd.cap);e.secondary=fd.secondary;e.weights=fd.weights;e.notes=fd.notes;e.reviewed=fd.reviewed==='on';if(!e.names.bg||!e.names.en||!Number.isFinite(e.target)||e.target<0||!Number.isFinite(e.cap)||e.cap<0||['race','series','medley'].includes(e.mode)&&e.target<=0||['series','medley'].includes(e.mode)&&!Number.isInteger(e.target)){toast(t('error'));return;}if(!['race','reps','series','medley','height'].includes(e.mode))e.secondary='none';try{const base=drafts.event?.base||eventFormBase;commit([{path:['data','events'],prev:base,next:events}],'Configure event: '+eventName(e));delete drafts.event;persist();$('#dialog').close();applySetupDraft();}catch{toast(t('error'));}}});
$('#importFile').addEventListener('change',async ev=>{const file=ev.target.files[0];if(!file)return;try{if(file.size>30000000)throw Error();const parsed=JSON.parse(await file.text());if(parsed.app!=='StrongmanArena'||parsed.version!==1)throw Error();SM.validateDocument(parsed.doc);if(!await seasonConfirm(t('confirmrestore')))return;backup();if(sync){if(queue.length){toast(t('onlineleave'));return;}changeData(parsed.doc.data,'Restore competition');drafts=parsed.drafts||{};}else{doc=parsed.doc;queue=[];drafts=parsed.drafts||{};}view=d().phase==='setup'?'setup':'standings';persist();render();}catch{toast(t('invalidbackup'));}ev.target.value='';});
window.addEventListener('storage',ev=>{if(ev.key===STORE){readOnlyTab=true;storageNotice();toast(lang==='bg'?'Друга страница е променила данните. Използвайте една страница на устройство.':'Another tab changed data. Use one tab per device.');}});
window.addEventListener('beforeunload',ev=>{if(readOnlyTab)return;captureDraft();captureSetupDraft();persist();if(storagePending&&!storageDurable){ev.preventDefault();ev.returnValue='';}});
async function boot(){try{const saved=await SMStorage.load();if(saved&&(needsIndexedRecovery||saved.stamp>storageStamp)){loadSaved(JSON.parse(saved.payload));damagedStorage=null;needsIndexedRecovery=false;}else if(needsIndexedRecovery)damagedStorage=localStorage.getItem(STORE); }catch{if(needsIndexedRecovery)try{damagedStorage=localStorage.getItem(STORE);}catch{}}storageReady=true;render();applySetupDraft();if(drafts.event&&d().phase==='setup'&&d().events.some(e=>e.id===drafts.event.id)){editEvent(drafts.event.id);}setInterval(pump,1200);if(sync)pump();
storageNotice();}
boot();
